import math

def c(n):
    if n <= 1:
        return 0
    return 2 * (math.log(n - 1) + 0.5772156649) - (2 * (n - 1) / n)

def anomaly_score(avg_path_length, n):
    return 2 ** (-avg_path_length / c(n))

n = 10000  # dataset size
for h in [12, 8, 5, 3, 1.5]:
    s = anomaly_score(h, n)
    if s > 0.9:
        verdict = 'AUTO-CONTAIN'
    elif s > 0.7:
        verdict = 'INVESTIGATE'
    else:
        verdict = 'normal'
    print(f'avg path length={h:5.1f}  ->  score={s:.3f}  ->  {verdict}')
